  public async applyTupleMutationsBatch(inputs: ReadonlyArray<ApplyTupleMutationsInput>, options: CommandBatchOptions): Promise<CommandBatchResult<ApplyTupleMutationsOutcome>> {
    if (!Number.isInteger(options.concurrency) || options.concurrency < 1 || options.concurrency > MAX_COMMAND_BATCH_CONCURRENCY || inputs.length < 1 || inputs.length > 4096) throw new Error("invalid command batch bounds");
    const start = options.checkpoint ?? 0;
    if (!Number.isInteger(start) || start < 0 || start > inputs.length) throw new Error("invalid command batch checkpoint");
    if (start === inputs.length) return { items: [], checkpoint: start };
    if (this.transport.executeCommandBatch !== undefined) { const result = await this.transport.executeCommandBatch(applyTupleMutations(inputs[start]!), inputs, options.concurrency, start, this.commandAttemptBudget); options.onProgress?.({ completed: result.checkpoint, total: inputs.length, checkpoint: result.checkpoint }); return result; }
    const items: CommandBatchItem<ApplyTupleMutationsOutcome>[] = [];
    let next = start;
    let completed = start;
    let checkpoint = start;
    const completedAfterCheckpoint = new Set<number>();
    const worker = async (): Promise<void> => { while (true) { const index = next++; if (index >= inputs.length) return; try { items.push({ index, result: await this.applyTupleMutations(inputs[index]!) }); } catch (error) { items.push({ index, error }); } completed += 1; completedAfterCheckpoint.add(index); while (completedAfterCheckpoint.delete(checkpoint)) checkpoint += 1; options.onProgress?.({ completed, total: inputs.length, checkpoint }); } };
    await Promise.all(Array.from({ length: Math.min(options.concurrency, inputs.length - start) }, worker));
    items.sort((left, right) => left.index - right.index);
    return { items, checkpoint };
  }

